# ------------------------------------------------------------------
with tab_sop:
    st.subheader("Mary-X spheroid culture and EV collection SOP")
    st.caption(
        f"Version {MARYX_SOP_VERSION} · Updated {MARYX_SOP_UPDATED} · "
        f"Culture source: {MARYX_SOP_SOURCE}"
    )
    render_sop_editor()

    st.image(MARYX_SUCROSE_DIAGRAM_SVG, width=1000)
    st.caption(
        "Adapted from the supplied whitepaper's Figure 2 and Protocol 2: only the 30% sucrose "
        "route is shown. Your 2,000 × g / 15-minute setting and −80 °C storage are retained. "
        "The first high-speed spin retains the sucrose layer; the second retains the pellet."
    )
    with st.expander("Two sample origins and storage", expanded=False):
        st.image(MARYX_SAMPLE_DIAGRAM_SVG, width=1000)
        st.caption(
            "Internal = intracellular membrane/vesicle-enriched preparation; external = "
            "conditioned-medium EV-enriched preparation. Keep the two samples separate at −80 °C. "
            "The source protocol is for conditioned medium; the intracellular application requires validation."
        )
    st.markdown(MARYX_SOP_NOTES)
    st.download_button(
        "⬇️ Download SOP as TXT",
        data=MARYX_SOP_TEXT.encode("utf-8"),
        file_name=f"MaryX_culture_and_EV_collection_SOP_v{MARYX_SOP_VERSION.replace('.', '_')}.txt",
        mime="text/plain",
        key="download_maryx_sop",
    )
    st.download_button(
        "⬇️ Download selected sucrose workflow as SVG",
        data=MARYX_SUCROSE_DIAGRAM_SVG.encode("utf-8"),
        file_name="MaryX_30_percent_sucrose_workflow.svg",
        mime="image/svg+xml",
        key="download_maryx_sucrose_diagram",
    )
    st.download_button(
        "⬇️ Download sample diagram as SVG",
        data=MARYX_SAMPLE_DIAGRAM_SVG.encode("utf-8"),
        file_name="MaryX_two_sample_workflow.svg",
        mime="image/svg+xml",
        key="download_maryx_sample_diagram",
    )
    for section_number, (section_title, section_body) in enumerate(MARYX_SOP_SECTIONS):
        with st.expander(section_title, expanded=section_number < 3):
            st.markdown(section_body)

    st.markdown("---")
    st.subheader("Reference PDFs")
    st.caption("Download the original reference files supplied with this SOP.")
    for reference_number, reference in enumerate(MARYX_REFERENCE_PDFS):
        st.download_button(
            reference["label"],
            data=base64.b64decode(reference["data_b64"], validate=True),
            file_name=reference["file_name"],
            mime="application/pdf",
            key=f"maryx_reference_pdf_{reference_number}",
        )

